def main() -> None:
    out = {"version": 1, "niches": {}}
    missing = []
    for name in names:
        key = name.replace("\u2019", "'").replace("\u2018", "'")
        row = T.get(name) or T.get(key)
        if not row:
            missing.append(name)
            continue
        out["niches"][name] = row
    path = ROOT / "pipeline" / "niche_title_glossary.json"
    path.write_text(json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8")
    print("written", len(out["niches"]), "missing", len(missing))
    if missing:
        print(missing)
        raise SystemExit(1)


if __name__ == "__main__":
    main()
